}

int main(){
    mt19937_64 rng(555);
    for(int tc=0;tc<3000;tc++){
        int n=rng()%60+1;
        ll p=(ll)(rng()%12)+1;
        vector<ll> a(n+1,0);
        for(int i=1;i<=n;i++) a[i]=(ll)(rng()%41)-20;
        int m=rng()%20+1;
        vector<array<ll,3>> actual(m);
        vector<ll> expected(m);
        ll lastans=0;
        for(int i=0;i<m;i++){
            int l=rng()%n+1, r=rng()%n+1; if(l>r) swap(l,r);
            ll x=rng()%p;
            ll ans=bruteAns(a,l,r,x,p);
            expected[i]=ans;
            // encode
            actual[i][0]=(ll)l ^ lastans;
            actual[i][1]=(ll)r ^ lastans;
            actual[i][2]=x ^ lastans;
            lastans=((ans%n)+n)%n;
        }
        vector<ll> got=origSolve(n,m,p,a,actual);
        if(got!=expected){
            printf("MISMATCH tc=%d n=%d p=%lld m=%d\n",tc,n,p,m);
            for(int i=1;i<=n;i++) printf("%lld ",a[i]); printf("\n");
            for(int i=0;i<m;i++) printf("Q %lld %lld %lld exp %lld got %lld\n",actual[i][0],actual[i][1],actual[i][2],expected[i],got[i]);
            return 0;
        }
    }
    printf("ALL OK\n");
    return 0;
}

