            if(!(R&1)) rgt[nr++]=R--;
            L>>=1; R>>=1;
        }
        for(int i=0;i<nl;i++){
            int u=lft[i];
            ll Trel = T - S[lo[u]];
            int a_=len[u];
            const ll* vp = pool.data()+off[u];
            int lo2=0, hi=a_;
            while(lo2<hi){ int mid=(lo2+hi)>>1; if(vp[mid]>=Trel) lo2=mid+1; else hi=mid; }
            k += lo2;
            T += (ll)lo2 * p;
        }
        for(int i=nr-1;i>=0;i--){
            int u=rgt[i];
            ll Trel = T - S[lo[u]];
            int a_=len[u];
