#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

struct Seg {
    int n,sz; ll p; vector<ll> S; vector<ll> pool; vector<int> off,len,lo;
    Seg(int n_,ll p_,vector<ll>&a){
        n=n_; p=p_; S.assign(n+1,0); for(int i=1;i<=n;i++)S[i]=S[i-1]+a[i];
        sz=1; while(sz<n) sz<<=1; int N=2*sz;
        off.assign(N,0); len.assign(N,0); lo.assign(N,0);
        int levels=1; for(int t=sz;t>1;t>>=1) levels++;
        pool.reserve((size_t)n*levels+16);
        for(int i=0;i<sz;i++){ off[sz+i]=(int)pool.size(); lo[sz+i]=i; if(i<n){ pool.push_back(a[i+1]); len[sz+i]=1; } else len[sz+i]=0; }
        const ll NEG=LLONG_MIN/4;
        for(int u=sz-1;u>=1;u--){
            int lc=2*u,rc=2*u+1;
            int oA=off[lc],lA=len[lc],oB=off[rc],lB=len[rc];
            ll SumA=S[lo[lc]+lA]-S[lo[lc]];
            off[u]=(int)pool.size(); int c=0,bb=0;
            while(c<lA||bb<lB){
                ll nextA=(c<lA)?pool[oA+c]:NEG;
                ll nextB=(bb<lB)?(pool[oB+bb]-(ll)c*p+SumA):NEG;
                if(nextA>=nextB){ ll T=nextA; c++; int before=bb; while(bb>=1&&(pool[oB+bb-1]-(ll)c*p+SumA)<T) bb--; if(bb==before) pool.push_back(T); }
                else { ll T=nextB; bb++; pool.push_back(T); }
            }
            len[u]=(int)pool.size()-off[u];
            lo[u]=lo[lc];
        }
    }
    ll query(int l,int r,ll x) const {
        ll T=S[l-1]-x+p; ll k=0; int L=(l-1)+sz,R=(r-1)+sz;
        int lft[64],rgt[64],nl=0,nr=0;
        while(L<=R){ if(L&1)lft[nl++]=L++; if(!(R&1))rgt[nr++]=R--; L>>=1;R>>=1; }
        for(int i=0;i<nl;i++){ int u=lft[i]; ll Trel=T-S[lo[u]]; int a_=len[u]; const ll* vp=pool.data()+off[u]; int lo2=0,hi=a_; while(lo2<hi){int mid=(lo2+hi)>>1; if(vp[mid]>=Trel)lo2=mid+1; else hi=mid;} k+=lo2; T+=(ll)lo2*p; }
        for(int i=nr-1;i>=0;i--){ int u=rgt[i]; ll Trel=T-S[lo[u]]; int a_=len[u]; const ll* vp=pool.data()+off[u]; int lo2=0,hi=a_; while(lo2<hi){int mid=(lo2+hi)>>1; if(vp[mid]>=Trel)lo2=mid+1; else hi=mid;} k+=lo2; T+=(ll)lo2*p; }
        return x+(S[r]-S[l-1])-k*p;
    }
};

int main(){
    mt19937_64 rng(2024);
    for(int tc=0;tc<3000;tc++){
        int n=rng()%2000+1;
        ll p; int md=rng()%3; if(md==0)p=1; else if(md==1)p=(ll)(rng()%1000)+1; else p=(ll)(rng()%1000000000ULL)+1;
        vector<ll> a(n+1);
        for(int i=1;i<=n;i++){ int m2=rng()%2; if(m2==0)a[i]=(ll)(rng()%2000000001ULL)-1000000000LL; else a[i]=(ll)(rng()%(2*p))-(ll)p; }
        Seg seg(n,p,a);
        for(int q=0;q<20;q++){
            int l=rng()%n+1,r=rng()%n+1; if(l>r)swap(l,r); ll x=rng()%p;
            ll got=seg.query(l,r,x); ll cur=x; for(int j=l;j<=r;j++){ if(cur+a[j]>=p)cur=cur+a[j]-p; else cur=cur+a[j]; }
            if(got!=cur){ printf("MISMATCH tc=%d n=%d p=%lld l=%d r=%d x=%lld got=%lld exp=%lld\n",tc,n,p,l,r,x,got,cur); return 0; }
        }
    }
    printf("ALL OK\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

static const int RB=1<<20;
static char rbuf[RB]; static int rpos=0, rlen=0;
static inline int gc(){ if(rpos==rlen){ rlen=(int)fread(rbuf,1,RB,stdin); rpos=0; if(rlen<=0) return EOF; } return (unsigned char)rbuf[rpos++]; }
static inline bool readInt(ll&out){
    int c=gc(); if(c==EOF) return false;
    while(c!='-'&&(c<'0'||c>'9')){ c=gc(); if(c==EOF) return false; }
    ll sign=1; if(c=='-'){ sign=-1; c=gc(); }
    ll num=0; while(c>='0'&&c<='9'){ num=num*10+(c-'0'); c=gc(); }
    out=num*sign; return true;
}
static char wbuf[1<<20]; static int wpos=0;
static inline void wc(char c){ if(wpos==(1<<20)){ fwrite(wbuf,1,wpos,stdout); wpos=0; } wbuf[wpos++]=c; }
static void writeLL(ll v){ if(v==0){ wc('0'); wc('\n'); return; } if(v<0){ wc('-'); v=-v; } char t[24]; int k=0; while(v){ t[k++]=(char)('0'+v%10); v/=10; } while(k) wc(t[--k]); wc('\n'); }

int main(){
    ll n_,m_,p; readInt(n_); readInt(m_); readInt(p);
    int n=(int)n_, m=(int)m_;

    int sz=1; while(sz<n) sz<<=1;
    int N=2*sz;
    vector<int> off(N), len(N), lo(N,0);
    vector<ll> S(n+1,0);
    int levels=1; for(int t=sz;t>1;t>>=1) levels++;
    vector<ll> pool; pool.reserve((size_t)n*levels + 16);

    for(int i=0;i<sz;i++){
        off[sz+i]=(int)pool.size();
        lo[sz+i]=i;
        if(i<n){ ll v; readInt(v); S[i+1]=S[i]+v; pool.push_back(v); len[sz+i]=1; }
        else { len[sz+i]=0; }
    }
    const ll NEG=LLONG_MIN/4;
    for(int u=sz-1;u>=1;u--){
        int lc=2*u, rc=2*u+1;
        int oA=off[lc], lA=len[lc], oB=off[rc], lB=len[rc];
        ll SumA = S[lo[lc]+lA] - S[lo[lc]];
        off[u]=(int)pool.size();
        int c=0, bb=0;
        while(c<lA || bb<lB){
            ll nextA = (c<lA) ? pool[oA+c] : NEG;
            ll nextB = (bb<lB) ? (pool[oB+bb] - (ll)c*p + SumA) : NEG;
            if(nextA >= nextB){
                ll T=nextA; c++;
                int before=bb;
                while(bb>=1 && (pool[oB+bb-1] - (ll)c*p + SumA) < T) bb--;
                if(bb==before) pool.push_back(T);
            } else {
                ll T=nextB; bb++;
                pool.push_back(T);
            }
        }
        len[u]=(int)pool.size()-off[u];
        lo[u]=lo[lc];
    }

    ll lastans=0;
    for(int qi=0;qi<m;qi++){
        ll l,r,x; readInt(l); readInt(r); readInt(x);
        l^=lastans; r^=lastans; x^=lastans;
        ll T = S[l-1]-x+p;
        ll k=0;
        int L=(int)(l-1)+sz, R=(int)(r-1)+sz;
        int lft[64], rgt[64], nl=0, nr=0;
        while(L<=R){
            if(L&1) lft[nl++]=L++;
            if(!(R&1)) rgt[nr++]=R--;
            L>>=1; R>>=1;
        }
        for(int i=0;i<nl;i++){
            int u=lft[i];
            ll Trel=T-S[lo[u]];
            int a_=len[u];
            const ll* vp=pool.data()+off[u];
            int lo2=0, hi=a_;
            while(lo2<hi){ int mid=(lo2+hi)>>1; if(vp[mid]>=Trel) lo2=mid+1; else hi=mid; }
            k+=lo2;
            T+=(ll)lo2*p;
        }
        for(int i=nr-1;i>=0;i--){
            int u=rgt[i];
            ll Trel=T-S[lo[u]];
            int a_=len[u];
            const ll* vp=pool.data()+off[u];
            int lo2=0, hi=a_;
            while(lo2<hi){ int mid=(lo2+hi)>>1; if(vp[mid]>=Trel) lo2=mid+1; else hi=mid; }
            k+=lo2;
            T+=(ll)lo2*p;
        }
        ll ans = x + (S[r]-S[l-1]) - k*p;
        writeLL(ans);
        lastans = ((ans % n) + n) % n;
    }
    if(wpos) fwrite(wbuf,1,wpos,stdout);
    return 0;
}
